css:
:root {
  --bg: #f7f7f5;
  --card: #ffffff;
  --text: #18181b;
  --muted: #71717a;
  --line: #e4e4e7;
  --soft: #f4f4f5;
  --accent: #2563eb;
  --accent-soft: #eff6ff;
  --code-bg: #f8fafc;
  --code-text: #1f2937;
}

.card,
.card.nightMode,
.nightMode .card {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Apple SD Gothic Neo", "Noto Sans KR", "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.65;
  text-align: left;
  color: var(--text) !important;
  background: var(--bg) !important;
  padding: 28px 18px;
}

.problem-card {
  max-width: 720px;
  margin: 0 auto;
  padding: 28px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
}

.meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 18px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--soft);
  color: var(--muted);
}

.badge.type {
  background: var(--accent-soft);
  border-color: #dbeafe;
  color: var(--accent);
}

.question {
  margin: 0;
  font-size: 22px;
  line-height: 1.45;
  font-weight: 760;
  letter-spacing: -0.025em;
  white-space: pre-wrap;
}

.divider {
  height: 1px;
  margin: 24px 0;
  background: var(--line);
}

.label {
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.answer {
  white-space: pre-wrap;
  font-size: 17px;
}

.principles {
  margin-top: 22px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--soft);
  color: #3f3f46;
  font-size: 14px;
}

pre {
  margin: 14px 0;
  padding: 14px 16px;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--code-bg);
}

code,
pre code {
  font-family: "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  font-size: 0.9em;
  color: var(--code-text) !important;
}

code {
  padding: 0.12em 0.35em;
  border-radius: 6px;
  background: var(--code-bg);
}

b,
strong {
  font-weight: 760;
}

a {
  color: var(--accent) !important;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}
